import sys, os, json, random, subprocess, pathlib; sys.path.insert(0,'/workspace/dev'); sys.path.insert(0,'/workspace')
from harness import *
from wire import envelope, stream, crypto, datagram, trace, v as vmin
def consistent(off,n): return bytes(((off+i)*7+3)&0xff for i in range(n))
def widths(value): return [w for w in (1,2,4,8) if value < 2**(8*w-2)]
random.seed(2000)
def vw(value): return vmin(value, random.choice(widths(value)))
# replicate gen_trace(2000) but record bodies
events=[{'keys':['I','H','A']}]; meta=[]
pn={'I':0,'H':0,'A':0}; ncids={}
for e in range(80):
    lvl=random.choice(['I','H','A'])
    bodies=[]; desc=[]
    for f in range(random.randint(1,6)):
        k=random.randrange(10)
        rid=random.choice([0,4,8,12]); uid=random.choice([2,6,10]); sid=random.choice([1,5]); suid=random.choice([3,7])
        if k==0:
            off=random.randrange(0,60)*4; n=random.randrange(0,40)
            s=random.choice([rid,uid,sid]); oo=random.random()<0.8
            bodies.append(stream(s, off, consistent(off,n), fin=False, offset=oo, length=True)); desc.append(('stream',s,off,n,oo))
        elif k==1:
            off=random.randrange(0,60)*4; n=random.randrange(0,40); bodies.append(crypto(off, consistent(off,n))); desc.append(('crypto',off,n))
        elif k==2:
            lg=random.randrange(0,300)
            b=bytes([random.choice([2,3])])+vw(lg)+vw(random.randrange(5))+vw(0)+vw(random.randrange(0,lg+1))
            ecn = b[0]==3
            if ecn: b+=vw(1)+vw(2)+vw(3)
            bodies.append(b); desc.append(('ack',lg,ecn))
        elif k==3: bodies.append(b'\x00'*random.randrange(1,5)+b'\x01'); desc.append(('pad',))
        elif k==4: bodies.append(b'\x10'+vw(random.randrange(0,10**6))); desc.append(('maxdata',))
        elif k==5: bodies.append(b'\x15'+vw(random.choice([rid,uid,sid]))+vw(0)); desc.append(('sdb',))
        elif k==6: bodies.append(b'\x11'+vw(random.choice([rid,sid,suid]))+vw(random.randrange(10**4))); desc.append(('maxsd',))
        elif k==7:
            sq=random.randrange(1,4); ncids[sq]=bytes([0xd0+sq])
            bodies.append(b'\x18'+vw(sq)+vw(0)+b'\x01'+ncids[sq]+b'\x22'*16); desc.append(('ncid',sq))
        elif k==8:
            c=random.randrange(9)
            if c==0: bodies.append(b'\x14'+vw(3)); desc.append(('dblk',))
            elif c==1: bodies.append(b'\x16'+vw(2)); desc.append(('sblk',))
            elif c==2: bodies.append(b'\x17'+vw(1)); desc.append(('sblk',))
            elif c==3: bodies.append(b'\x1a'+b'12345678'); desc.append(('pc',))
            elif c==4: bodies.append(b'\x1b'+b'87654321'); desc.append(('pr',))
            elif c==5: bodies.append(b'\x31'+vw(2)+b'xy'); desc.append(('dg',))
            elif c==6: bodies.append(b'\x05'+vw(random.choice([rid,sid,suid]))+vw(3)); desc.append(('stop',))
            elif c==7: bodies.append(b'\x04'+vw(random.choice([rid,uid,sid]))+vw(7)+vw(10**9)); desc.append(('reset',))
            else: bodies.append(b'\x19'+vw(1)); desc.append(('retire',))
        else: bodies.append(b'\x06'+vw(random.randrange(0,200)*4)+vw(0)); desc.append(('crypto0',))
    if lvl!='A':
        keep=[(b,d) for b,d in zip(bodies,desc) if b[:1] in (b'\x00',b'\x01',b'\x02',b'\x03',b'\x06')]
        bodies=[b for b,d in keep] or [b'\x01']; desc=[d for b,d in keep] or [('ping',)]
    body=b''.join(bodies)
    w=envelope(lvl, pn[lvl], body, width=random.choice([1,2,4]), cid=random.choice([b'\xaa',b'\xbb']), phase=0)
    pn[lvl]+=1
    events.append(datagram(w, auth=(0,))); meta.append((lvl,body,desc))
r = run1(events, local_bidi=2, local_uni=2)
for i,p in enumerate(r['packets']):
    if p['status'] not in ('OK','PEER_CLOSE'):
        print('event',p['event'],'status',p['status'],'closed',r['closed'])
        lvl,body,desc = meta[p['event']-1]
        print(' level',lvl,'desc',desc)
        print(' body',body.hex())
        break
